package dev.pocketengine.features.local.project;

import static org.junit.Assert.*;
import android.app.Application;
import dev.pocketengine.core.*;
import dev.pocketengine.features.local.LocalModule;
import dev.pocketengine.store.TaskStore;
import java.lang.reflect.*;
import java.nio.file.*;
import java.util.concurrent.atomic.AtomicReference;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.*;

/** Reuses the actual original Vite/JNI/SQL factory, not a model JSON live flag. */
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=Application.class)
@ConscryptMode(ConscryptMode.Mode.OFF)
public final class ProjectOwnerLiveFileSaveJourneyTest {
    private ProjectLiveRunnerJourneyTest original;private Object factory;private ProjectCapabilityPort port;private LocalModule local;private TaskStore tasks;private TaskStoreProjectHost host;private RunControl control;private String task,run,project,checkout;private int epoch;private RunJournal journal;
    @SuppressWarnings("unchecked") private static <T>T field(Object object,String key)throws Exception{var f=object.getClass().getDeclaredField(key);f.setAccessible(true);return (T)f.get(object);}
    private void approve(JSONObject plan)throws Exception{var method=factory.getClass().getDeclaredMethod("approveControlledOwnerPlan",JSONObject.class);method.setAccessible(true);try{method.invoke(factory,plan);}catch(InvocationTargetException failed){if(failed.getCause() instanceof Exception)throw (Exception)failed.getCause();throw failed;}}
    @Before public void setup()throws Exception{original=new ProjectLiveRunnerJourneyTest();original.create();factory=field(original,"factory");port=field(original,"port");local=field(original,"local");tasks=field(original,"tasks");control=field(original,"original");task=field(original,"taskId");run=field(original,"run");epoch=field(original,"epoch");project=field(original,"project");checkout=field(original,"checkout");host=field(factory,"host");journal=tasks.journal(task,run,epoch,control);}
    @After public void close()throws Exception{if(original!=null)original.close();}
    private JSONObject tool(String name,JSONObject args)throws Exception{String operation=port.sideEffecting(name)?journal.beginOperation(name,args):null;JSONObject input=new JSONObject(args.toString());if(operation!=null)input.put("_hostOperationId",operation);JSONObject receipt=port.execute(name,input,control);if(operation!=null)journal.finishOperation(operation,receipt);assertNotEquals("original native tool must not silently require another approval: "+receipt,"approval_required",receipt.optString("code"));return receipt;}
    private JSONObject plan(String intent,JSONObject extras)throws Exception{String digest=ProjectSources.describe(local.handle("export",new JSONObject().put("checkoutId",checkout))).getString("sourceDigest");JSONObject input=new JSONObject(extras.toString()).put("intent",intent).put("ecosystem","node").put("expectedSourceDigest",digest);JSONObject reference=tool("project_plan",input);JSONObject args=reference.has("planRef")?new JSONObject().put("planRef",reference.getString("planRef")).put("planDigest",reference.getString("planDigest")).put("stepId",intent.equals("dependencies")?"dependencies":"run"):new JSONObject().put("plan",reference.getJSONObject("plan")).put("stepId",intent.equals("dependencies")?"dependencies":"run");JSONObject full=tasks.projectArguments(task,run,epoch,args).getJSONObject("plan");approve(full);return new JSONObject().put("plan",full).put("stepId",full.getJSONArray("steps").getJSONObject(0).getString("id"));}
    @Test public void ownerHandSaveKeepsExactOriginalServiceLiveAndDraftCasWhileLateEditsAndReadOnlyRecoveryRemainSafe()throws Exception{
        JSONObject dependencies=tool("project_execute",plan("dependencies",new JSONObject()));assertEquals(dependencies.toString(),0,dependencies.getInt("exitCode"));
        JSONObject launch=tool("project_execute",plan("run",new JSONObject().put("runMode","owned_service").put("devWatch",true).put("liveEditPaths",new JSONArray().put("src/budget.js"))));assertEquals("project_running",launch.getString("code"));String service=launch.getString("operationId"),ack=launch.getString("launchAckIdentity");assertTrue(journal.hasNativeProjectRunningAck(service,launch));
        JSONObject read=local.handle("reviewFile",new JSONObject().put("checkoutId",checkout).put("path","src/budget.js"));ProjectFileDraft draft=ProjectFileDraft.empty(project,checkout,"src/budget.js",false).observe(read);String changed=draft.text.replace("cents / 100","(cents + 500) / 100");assertNotEquals(draft.text,changed);draft=draft.edit(changed);var submitted=draft.saveIntent();var nativeOwner=new ProjectOwnerLiveFileSave(tasks,local,host,id->id.equals(task)?control:null);RunControl observer=new RunControl();var review=nativeOwner.review(task,submitted,observer);assertFalse(review.metadata().getBoolean("newRunCreated"));assertEquals(service,review.metadata().getString("serviceExecutionId"));
        assertThrows(IllegalStateException.class,()->local.handle("writeFile",submitted.input()));AtomicReference<JSONObject> originalLocator=new AtomicReference<>();var result=nativeOwner.execute(review,observer,originalLocator::set);assertTrue("actual native same-service write must complete: "+result.json(),result.completed());assertNotNull(originalLocator.get());assertFalse(control.isCancelled());assertEquals(run,tasks.get(task,false).getString("runId"));assertEquals(epoch,tasks.get(task,false).getInt("coordinatorEpoch"));
        ProjectFileDraft newer=draft.edit(changed+"\n// owner typed after submitting\n");ProjectFileDraft acknowledged=newer.saved(submitted,result.json());assertTrue(acknowledged.dirty());assertEquals(newer.text,acknowledged.text);assertEquals(changed,acknowledged.baseContent);assertEquals(changed,local.handle("readFile",submitted.input()).getString("content"));
        JSONObject actual=tool("project_status",new JSONObject().put("executionId",service));assertEquals("running",actual.getString("serviceStatus"));assertEquals(ack,actual.getString("launchAckIdentity"));assertFalse(actual.getBoolean("resourcesReleased"));int before=tasks.get(task,false).getJSONArray("operations").length();assertTrue(nativeOwner.execute(review,observer,value->{throw new AssertionError("same Review may not dispatch twice");}).completed());assertEquals(before,tasks.get(task,false).getJSONArray("operations").length());assertTrue(nativeOwner.query(originalLocator.get()).completed());
        assertThrows(Exception.class,()->nativeOwner.review(task,submitted,new RunControl()));ProjectFileDraft config=ProjectFileDraft.empty(project,checkout,"package.json",false).observe(local.handle("reviewFile",new JSONObject().put("checkoutId",checkout).put("path","package.json")));assertThrows(Exception.class,()->nativeOwner.review(task,config.edit(config.text+"\n").saveIntent(),new RunControl()));
        // A storage/UI locator failure before native dispatch is a real definite no-write;
        // it does not cancel the original task or pretend a possibly-entered write vanished.
        ProjectFileDraft next=ProjectFileDraft.empty(project,checkout,"src/budget.js",false).observe(local.handle("reviewFile",submitted.input())).edit(changed+"\n// not dispatched\n");var noWrite=nativeOwner.review(task,next.saveIntent(),new RunControl());AtomicReference<JSONObject> failedLocator=new AtomicReference<>();assertThrows(Exception.class,()->nativeOwner.execute(noWrite,new RunControl(),value->{failedLocator.set(value);throw new IllegalStateException("controlled owner locator persist failure before native entry");}));assertEquals(changed,local.handle("readFile",submitted.input()).getString("content"));assertEquals("not_dispatched",nativeOwner.query(failedLocator.get()).json().getString("status"));assertFalse(control.isCancelled());
        JSONObject stopped=tool("project_stop",new JSONObject().put("executionId",service));assertEquals(stopped.toString(),"project_stop_confirmed",stopped.optString("code"));assertTrue(stopped.toString(),stopped.optBoolean("processTerminal"));assertTrue(stopped.toString(),stopped.optBoolean("resourcesReleased"));JSONObject observed=stopped.getJSONObject("observation");assertTrue(observed.toString(),observed.getBoolean("receiptReceived"));assertTrue(observed.toString(),observed.getBoolean("processExited"));assertTrue(observed.toString(),observed.getBoolean("processGroupAbsent"));assertTrue(observed.toString(),observed.getBoolean("resourcesReleased"));assertTrue(observed.toString(),observed.getString("status").matches("completed|failed"));assertTrue(observed.opt("exitCode") instanceof Integer||observed.opt("exitCode") instanceof Long);assertFalse(control.isCancelled());assertNotNull(journal.projectServiceExitEvidence(new JSONArray().put(service)));assertFalse(tasks.hasUnresolved(task));
        System.out.println("C2_OWNER_LIVE_SAVE actual native original dev-watch approval/ref, same task/run/epoch and native lease, hand source SHA CAS, late text retained, original-only query/no replay, config/stale-source rejected, pre-entry locator failure definite, original stop/drain; no ARM/provider or rendered UI claim.");
    }
}
